import{_ as n,l as i,o as e,c as s,v as t,p as l,x as o,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"复制式 GC","description":"","frontmatter":{"title":"复制式 GC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/copying-gc.md","filePath":"cs/copying-gc.md","lastUpdated":1789023840000}'),h={name:"cs/copying-gc.md"};function m(_,a,g,u,C,f){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="复制式-gc" tabindex="-1">复制式 GC <a class="header-anchor" href="#复制式-gc" aria-label="Permalink to &quot;复制式 GC&quot;">​</a></h1><div class="epigraph"><p>堆分成 from 与 to。从根出发把活对象搬到 to，留下转发指针。结束后交换半区。碎片自然消失，代价是堆只用一半。</p><footer>—— 据 Cheney, A Nonrecursive List Compacting Algorithm, 1970；Jones, Hosking and Moss, The Garbage Collection Handbook；主干[标记清除与分代](/cs/gc-mark-gen) 整理</footer></div><p>上一课<a href="/cs/jit-escape-analysis">JIT 逃逸</a> 减少分配。仍逃逸的对象进堆。主干 GC 课有标记-清扫直觉。缺口是<strong>复制式</strong>：Cheney 扫描、转发。内存管理课序从这里开始。引用计数下一课对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标记-清扫有碎片，分配要空闲表。复制：bump 指针在 to 区线性分配活对象。缺口是<strong>搬运与指针更新</strong>，不是逃逸分类。</p><p>Cheney：用 to 区当队列，广度扫描，无需递归栈。</p><h3 id="半区不是「浪费一半就慢一倍」" tabindex="-1">半区不是「浪费一半就慢一倍」 <a class="header-anchor" href="#半区不是「浪费一半就慢一倍」" aria-label="Permalink to &quot;半区不是「浪费一半就慢一倍」&quot;">​</a></h3><p>吞吐常更好（只碰活对象）。空间换时间。分代后幼代用复制，老年代另策略——后课。</p><p><span class="marginnote">Cheney 1970。Appel 的简单分代。Jones 手册。主干 runtime-gc、gc-mark-gen。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>翻转半区。扫描根，搬迁，写转发。扫描 to 区新对象的指针，直到队列空。更新栈与寄存器。JIT：安全点上的栈图给出根。</p>',11)),(e(),l(d,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%22%5D%20--%3E%20COPY%5B%22%E6%90%AC%E5%88%B0%20to%22%5D%0A%20%20COPY%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%E6%8C%87%E9%92%88%22%5D%0A%20%20FWD%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%20to%20%E5%8C%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与精确 vs 保守：保守不能随便搬（不清楚是不是指针）。复制式通常要精确根。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>大对象可进独立区不复制。多线程：每个线程 TLAB，后课。不要在非安全点搬对象，JIT 寄存器里的指针会丢。</p><p>与 deopt 物化：新对象当分配，可直接在 to 或 TLAB。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写引用计数。后课默认：幼代常用复制。下一课引用计数 GC。</p><p>也不把复制当 memcpy 课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复制式：搬活对象，消碎片，堆用半区。</li><li>Cheney 用 to 区当工作队列。</li><li>需要精确根与安全点。</li><li>出处：Cheney, 1970；Jones et al. 手册。</li></ul>',9))])}const b=n(h,[["render",m]]);export{A as __pageData,b as default};
